#include <functional>
#include <QGuiApplication>
#include <QQmlApplicationEngine>
#include <QQmlContext>
#include <QCommandLineParser>
#include <QTimer>
#include <QLoggingCategory>
#include <QQuickWindow>
#include <QImage>

#include "watch.h"            // generated by qt_add_statecharts from statechart/watch.scxml
#include "ScxmlTreeModel.h"
#include "TransitionTracer.h"
#include "ButtonRouter.h"
#include "WatchModel.h"

int main(int argc, char *argv[])
{
    QGuiApplication app(argc, argv);
    // <log> elements are spec-row markers for TransitionTracer, not console output.
    QLoggingCategory::setFilterRules(QStringLiteral("scxml.statemachine.debug=false"));
    app.setApplicationName(QStringLiteral("watch-me"));

    QCommandLineParser cli;
    cli.setApplicationDescription(QStringLiteral("Harel's 1987 watch statechart, executable."));
    cli.addHelpOption();
    QCommandLineOption autoInsert(QStringLiteral("auto-insert"), QStringLiteral("Insert the battery at start-up."));
    cli.addOption(autoInsert);
    QCommandLineOption script(QStringLiteral("script"),
        QStringLiteral("Semicolon separated steps run after start-up: 'a' (click), '+a'/'-a' (hold/release), "
                       "'wait:ms', or any SCXML event name."), QStringLiteral("steps"));
    QCommandLineOption grab(QStringLiteral("grab"), QStringLiteral("Save a screenshot of the window to <file> and quit."),
                            QStringLiteral("file"));
    QCommandLineOption grabDelay(QStringLiteral("grab-delay"), QStringLiteral("Delay before --grab (ms)."),
                                 QStringLiteral("ms"), QStringLiteral("800"));
    cli.addOption(script);
    cli.addOption(grab);
    cli.addOption(grabDelay);
    cli.process(app);

    WatchMachine machine;
    ScxmlTreeModel tree;
    tree.load(QStringLiteral(":/statechart/watch.scxml"));
    TransitionTracer tracer(&machine, &tree);
    WatchModel watch(&machine);
    watch.setRunning(true);
    ButtonRouter buttons(&machine);
    buttons.setTracer(&tracer);

    QQmlApplicationEngine engine;
    auto *ctx = engine.rootContext();
    ctx->setContextProperty(QStringLiteral("machine"), &machine);
    ctx->setContextProperty(QStringLiteral("tree"), &tree);
    ctx->setContextProperty(QStringLiteral("tracer"), &tracer);
    ctx->setContextProperty(QStringLiteral("buttons"), &buttons);
    ctx->setContextProperty(QStringLiteral("watch"), &watch);

    QObject::connect(&engine, &QQmlApplicationEngine::objectCreationFailed, &app,
                     [] { QCoreApplication::exit(1); }, Qt::QueuedConnection);
    engine.load(QUrl(QStringLiteral("qrc:/WatchMe/qml/Main.qml")));

    machine.start();
    if (cli.isSet(autoInsert))
        QTimer::singleShot(0, &buttons, [&] { buttons.submit(QStringLiteral("battery.inserted")); });

    // Scripted interaction + screenshot, used for docs/screenshots (QQuickWindow::grabWindow).
    QStringList steps = cli.value(script).split(QLatin1Char(';'), Qt::SkipEmptyParts);
    const QString grabFile = cli.value(grab);
    const int delay = cli.value(grabDelay).toInt();
    std::function<void()> runNext;
    runNext = [&] {
        if (steps.isEmpty()) {
            if (!grabFile.isEmpty())
                QTimer::singleShot(delay, &app, [&] {
                    auto *w = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0));
                    if (w && !w->grabWindow().save(grabFile))
                        qWarning("could not save %s", qPrintable(grabFile));
                    QCoreApplication::quit();
                });
            return;
        }
        const QString s = steps.takeFirst().trimmed();
        int gap = 60;
        if (s.startsWith(QLatin1String("wait:"))) {
            gap = s.mid(5).toInt();
        } else if (s.size() == 1) {
            buttons.press(s);
            QTimer::singleShot(30, &buttons, [&buttons, s] { buttons.release(s); });
        } else if (s.size() == 2 && s[0] == u'+') {
            buttons.press(s.mid(1));
        } else if (s.size() == 2 && s[0] == u'-') {
            buttons.release(s.mid(1));
        } else {
            buttons.submit(s);
        }
        QTimer::singleShot(gap, &app, runNext);
    };
    QTimer::singleShot(200, &app, runNext);
    return app.exec();
}
